      ],
      "materiality_rationale": "Removing or reversing this relation changes the claim's stated anticipated discrimination and its justification for measuring R.",
      "resolution_rationale": "This generated, asserted relation requires its own inline resolution. No distinct frozen evaluated claim is supplied, and the primary claim cannot reference itself."
    },
    {
      "dependency_id": "R3K07-C1-D8",
      "subject": "R2 favors H2.",
      "dependency_classification": {
        "content_origin": "MAPPING_GENERATED",
