      ],
      "materiality_rationale": "Removing or reversing this relation changes the claim's stated anticipated discrimination and its justification for measuring R.",
      "resolution_rationale": "This generated, asserted relation requires its own inline resolution. No distinct frozen evaluated claim is supplied, and the primary claim cannot reference itself."
    },
    {
      "dependency_id": "R3K07-C1-D9",
      "subject": "These likelihoods license directional updating, not certainty.",
      "dependency_classification": {
        "content_origin": "SOURCE_SUPPLIED",
        "epistemic_function": "LIMIT",
        "assertion_mode": "REFERENCED_PREMISE",
        "origin_refs": [
          {
            "source_id": "R3K07-S",
            "source_type": "SOURCE_INSTRUMENT"
          }
        ],
        "rationale": "The source explicitly supplies this restriction. It constrains the strength of conclusions available from the likelihoods. The claim invokes that restriction through its directional wording, 'favors.'"
      },
      "resolution": "GROUNDING_REF",
      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K07-S",
          "role": "SUPPORT"
        }
      ],
      "materiality_rationale": "The restriction fixes the strength of the anticipated discrimination; certainty would materially expand the claim.",
      "resolution_rationale": "The supplied restriction is invoked at the same strength and scope, without adding a new limitation or asserting an observed update."
    }
  ],
  "closure_status": "COMPLETE",
